import six
from lxml import etree, objectify
from taf.internal.scf.exceptions import ScfCannotBeCreated
from taf.internal.scf.raml import Raml


class SCF:
    def __init__(self, scf_path=None):
        """Load a SCF file to work on it.
        If scf_path is not provided then an empty scf is created.

        :param scf_path: path to the SCF file or a file-like object
        :return: the SCF object with raml property
        """
        self._tree = None

        if scf_path:
            self._create_scf(scf_path)
        else:
            self._create_empty_scf(xmlns='raml21.xsd', raml_version="2.1")
        self._raml = Raml(self._tree)

    @property
    def raml(self):
        return self._raml

    def save(self, file_path, xml_declaration=True, encoding='UTF-8', standalone=True):
        """Save a SCF object to file.

        :param file_path: a path to the file to save
        :param xml_declaration: print xml declaration
        :param encoding: the encoding type of the xml file
        :param standalone: print if the xml file is a standalone version
        """
        tree_string = self.to_string(xml_declaration, encoding, standalone)
        with open(file_path, 'wt') as fp:
            fp.write(tree_string)

    def to_string(self, xml_declaration=True, encoding='UTF-8', standalone=True):
        tree_string = etree.tostring(self._tree,
                                     xml_declaration=xml_declaration,
                                     encoding=encoding,
                                     standalone=standalone,
                                     pretty_print=True)
        return tree_string.decode(encoding)

    def _create_scf(self, scf_path):
        try:
            if isinstance(scf_path, six.string_types):
                scf_file = open(scf_path, 'rb')
            else:
                scf_file = scf_path
            xml_content = scf_file.read()
            scf_file.close()
            self._tree = objectify.fromstring(xml_content)
        except Exception as e:
            raise ScfCannotBeCreated(str(e))

    def _create_empty_scf(self, xmlns, raml_version):
        xml_content = '<raml xmlns="{}" version="{}"><cmData></cmData></raml>'
        xml_content = xml_content.format(xmlns, raml_version)
        self._tree = objectify.fromstring(xml_content)
